//! Auto-generated ABI stubs for MSVBVM60.DLL exports.
//!
//! These stubs satisfy symbol resolution when linking against or running
//! binaries compiled with Visual Basic 6.0. Each stub returns 0 / S_OK by default
//! and logs when tracing is enabled.

macro_rules! define_stub {
    ($name:ident, $ordinal:expr) => {
        #[doc = concat!("ABI compatibility export stub for `", stringify!($name), "` (Ordinal ", stringify!($ordinal), ").")]
        #[doc = ""]
        #[doc = "# Returns"]
        #[doc = "Returns `0` (`S_OK`) by default. Logs the invocation when the `trace_calls` feature is enabled."]
        #[no_mangle]
        pub unsafe extern "system" fn $name() -> i32 {
            #[cfg(feature = "trace_calls")]
            #[cfg(feature = "std")]
            eprintln!("[msvbvm60 stub] Call to {} (Ordinal {})", stringify!($name), $ordinal);
            0
        }
    };
}

